"""Bounded Mac mining declarations. Only semantic data leaves this static reader."""
import copy
from .ship_models import section_bytes
from .declaration_layouts import recognize

def declaration_bytes(mach, address, size, name):
    if name!=b'__data':return section_bytes(mach,address,size,name)
    for section in mach.sections:
        if section['segment']==b'__DATA' and section['name']==name and section['offset'] and section['address']<=address and address+size<=section['address']+section['length']:
            offset=section['offset']+address-section['address']
            return mach.data[offset:offset+size],offset+mach.slice_offset
    return None

def extract_mining_drill(mach, arrival, flight):
    if mach.architecture!='x86_64':return {}
    try:
        if flight.get('scope')!='first_mining_flight_construction':return {}
        origin=arrival['provenance']['actor']
        if origin['bytes']!=315:return {}
        proof=recognize(mach,origin['offset'],[{k:[v[2],v[0],v[1],v[3]] for k,v in rows.items()} for rows in [LAYOUTS,MAC_ALTERNATE]],reader=declaration_bytes)
        if not proof:return {}
        result=copy.deepcopy(VALUES);result['provenance']=proof
        return result
    except (KeyError,TypeError,ValueError,IndexError,OverflowError):return {}

